insert into public.destinations(slug,name,region,tagline,description,sort,active) values ('yogyakarta','Yogyakarta','DI Yogyakarta',$j${"id": "Kota budaya yang tidak pernah terburu-buru", "en": "A cultural city that never rushes"}$j$::jsonb,$j${"id": "Candi berusia seribu tahun, kuliner yang membuat rindu, dan keraton yang masih hidup. Cocok untuk perjalanan santai bersama keluarga.", "en": "Thousand-year-old temples, food you will miss, and a living palace. Perfect for an unhurried family trip."}$j$::jsonb,10,true) on conflict (slug) do update set name=excluded.name,region=excluded.region,tagline=excluded.tagline,description=excluded.description,sort=excluded.sort;
insert into public.destinations(slug,name,region,tagline,description,sort,active) values ('bali','Bali','Bali',$j${"id": "Pulau yang punya ritme untuk semua jenis liburan", "en": "An island with a rhythm for every kind of holiday"}$j$::jsonb,$j${"id": "Dari sawah berundak Tegallalang sampai tebing Uluwatu. Bali nyaman dijelajah dengan mobil dan sopir yang paham rute dan jam macet.", "en": "From the terraces of Tegallalang to the cliffs of Uluwatu. Bali is easiest with a car and a driver who knows the routes and the traffic."}$j$::jsonb,20,true) on conflict (slug) do update set name=excluded.name,region=excluded.region,tagline=excluded.tagline,description=excluded.description,sort=excluded.sort;
insert into public.destinations(slug,name,region,tagline,description,sort,active) values ('lombok','Lombok','Nusa Tenggara Barat',$j${"id": "Pantai sepi, Gili jernih, dan Rinjani di kejauhan", "en": "Quiet beaches, clear Gilis, and Rinjani on the horizon"}$j$::jsonb,$j${"id": "Lebih tenang dari Bali, dengan pantai Mandalika, tiga Gili, dan desa Sasak yang ramah.", "en": "Calmer than Bali, with Mandalika beaches, three Gilis, and welcoming Sasak villages."}$j$::jsonb,30,true) on conflict (slug) do update set name=excluded.name,region=excluded.region,tagline=excluded.tagline,description=excluded.description,sort=excluded.sort;
insert into public.destinations(slug,name,region,tagline,description,sort,active) values ('karimunjawa','Karimunjawa','Jawa Tengah',$j${"id": "Kepulauan jernih yang dekat dari Jawa", "en": "Crystal-clear islands close to Java"}$j$::jsonb,$j${"id": "Snorkeling di perairan dangkal, hiu karang yang jinak, dan senja di dermaga. Berangkat dari Jepara atau Semarang.", "en": "Snorkelling in shallow water, gentle reef sharks, and sunsets on the pier. Depart from Jepara or Semarang."}$j$::jsonb,40,true) on conflict (slug) do update set name=excluded.name,region=excluded.region,tagline=excluded.tagline,description=excluded.description,sort=excluded.sort;
insert into public.destinations(slug,name,region,tagline,description,sort,active) values ('raja-ampat','Raja Ampat','Papua Barat Daya',$j${"id": "Surga bawah laut yang butuh persiapan", "en": "An underwater paradise that deserves preparation"}$j$::jsonb,$j${"id": "Gugusan karst di atas laut turquoise dan keanekaragaman terumbu karang tertinggi di dunia. Kami bantu atur homestay, kapal, dan izin masuk.", "en": "Karst islands above turquoise water and the richest coral diversity on Earth. We arrange homestays, boats and entry permits."}$j$::jsonb,50,true) on conflict (slug) do update set name=excluded.name,region=excluded.region,tagline=excluded.tagline,description=excluded.description,sort=excluded.sort;
insert into public.destinations(slug,name,region,tagline,description,sort,active) values ('bromo','Bromo','Jawa Timur',$j${"id": "Matahari terbit di atas lautan awan", "en": "Sunrise above a sea of clouds"}$j$::jsonb,$j${"id": "Berangkat dini hari, jeep ke lautan pasir, lalu naik tangga menuju kawah. Dingin tapi tidak terlupakan.", "en": "Leave before dawn, jeep across the sand sea, then climb the steps to the crater. Cold, but unforgettable."}$j$::jsonb,60,true) on conflict (slug) do update set name=excluded.name,region=excluded.region,tagline=excluded.tagline,description=excluded.description,sort=excluded.sort;
insert into public.packages(slug,title,summary,kind,destination_id,duration_days,price_from,price_note,highlights,itinerary,included,excluded,status,sort) values ('private-trip-yogyakarta',$j${"id": "Private Trip Yogyakarta 3 Hari", "en": "Private Yogyakarta Trip, 3 Days"}$j$::jsonb,$j${"id": "Borobudur saat fajar, Prambanan di sore hari, dan kuliner Malioboro dengan jadwal yang kamu atur sendiri.", "en": "Borobudur at dawn, Prambanan in the afternoon and Malioboro street food on a schedule you set yourself."}$j$::jsonb,'private',(select id from public.destinations where slug='yogyakarta'),3,1850000,$j${"id": "Harga per grup, sudah termasuk mobil dan sopir. Contoh harga; admin akan mengirim penawaran final.", "en": "Price per group, car and driver included. Sample price; our admin will send a final quote."}$j$::jsonb,$j$[{"id": "Sunrise di Candi Borobudur (opsi naik ke stupa dengan tiket terpisah)", "en": "Sunrise at Borobudur (stupa climb available with a separate ticket)"}, {"id": "Sunset di Candi Prambanan dan pertunjukan tari bila tersedia", "en": "Sunset at Prambanan and a dance performance when available"}, {"id": "Gudeg, bakpia, dan angkringan yang dipandu sopir lokal", "en": "Gudeg, bakpia and angkringan, guided by a local driver"}]$j$::jsonb,$j$[{"title": {"id": "Kota tua dan keraton", "en": "Old city and the palace"}, "text": {"id": "Jemput di hotel pukul 08.00. Keraton Yogyakarta, Taman Sari, lalu makan siang gudeg. Sore bebas di Malioboro.", "en": "Hotel pickup at 08:00. Kraton Yogyakarta, Taman Sari, then a gudeg lunch. Free afternoon in Malioboro."}}, {"title": {"id": "Borobudur dan Merapi", "en": "Borobudur and Merapi"}, "text": {"id": "Berangkat pukul 04.00 untuk sunrise Borobudur. Siang ke Kaliurang atau jeep lava tour Merapi sesuai minat.", "en": "Leave at 04:00 for Borobudur sunrise. Afternoon at Kaliurang or the Merapi lava jeep tour, as you prefer."}}, {"title": {"id": "Prambanan dan oleh-oleh", "en": "Prambanan and souvenirs"}, "text": {"id": "Candi Prambanan dan Ratu Boko saat senja. Belanja bakpia dan batik, lalu antar ke stasiun atau bandara.", "en": "Prambanan and Ratu Boko at sunset. Shop for bakpia and batik, then transfer to the station or airport."}}]$j$::jsonb,$j$[{"id": "Mobil + sopir 3 hari (12 jam per hari)", "en": "Car and driver for 3 days (12 hours a day)"}, {"id": "BBM, parkir, dan tol", "en": "Fuel, parking and tolls"}, {"id": "Air mineral di mobil", "en": "Bottled water in the car"}, {"id": "Rute dan jadwal yang bisa diubah", "en": "A flexible route and schedule"}]$j$::jsonb,$j$[{"id": "Hotel dan makan", "en": "Hotel and meals"}, {"id": "Tiket masuk wisata", "en": "Attraction tickets"}, {"id": "Tiket pesawat/kereta ke kota keberangkatan", "en": "Flights or train tickets to the departure city"}]$j$::jsonb,'published',10) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,kind=excluded.kind,destination_id=excluded.destination_id,duration_days=excluded.duration_days,price_from=excluded.price_from,price_note=excluded.price_note,highlights=excluded.highlights,itinerary=excluded.itinerary,included=excluded.included,excluded=excluded.excluded,status='published',sort=excluded.sort;
insert into public.packages(slug,title,summary,kind,destination_id,duration_days,price_from,price_note,highlights,itinerary,included,excluded,status,sort) values ('open-trip-bromo-sunrise',$j${"id": "Open Trip Bromo Sunrise 2 Hari 1 Malam", "en": "Bromo Sunrise Open Trip, 2 Days 1 Night"}$j$::jsonb,$j${"id": "Berangkat dini hari dari Malang, melihat matahari terbit dari Penanjakan, lalu menyusuri lautan pasir dengan jeep.", "en": "Leave Malang before dawn, watch sunrise from Penanjakan, then cross the sea of sand by jeep."}$j$::jsonb,'open',(select id from public.destinations where slug='bromo'),2,595000,$j${"id": "Per orang, minimal 4 peserta. Contoh harga; berlaku untuk keberangkatan dari Malang.", "en": "Per person, minimum 4 participants. Sample price; departure from Malang."}$j$::jsonb,$j$[{"id": "Sunrise Penanjakan 1", "en": "Penanjakan 1 sunrise"}, {"id": "Jeep 4x4 ke lautan pasir dan Bukit Teletubbies", "en": "4x4 jeep to the sand sea and Teletubbies Hill"}, {"id": "Naik ke kawah Bromo", "en": "Climb to the Bromo crater"}]$j$::jsonb,$j$[{"title": {"id": "Malang menuju Cemoro Lawang", "en": "Malang to Cemoro Lawang"}, "text": {"id": "Kumpul sore hari, perjalanan ke penginapan di kaki Bromo, makan malam dan istirahat. Jaket tebal wajib.", "en": "Meet in the afternoon, drive to the guesthouse below Bromo, dinner and rest. A warm jacket is essential."}}, {"title": {"id": "Sunrise, kawah, dan pulang", "en": "Sunrise, crater and return"}, "text": {"id": "Bangun pukul 02.30, jeep ke Penanjakan, lanjut ke lautan pasir dan kawah. Sarapan, lalu kembali ke Malang sebelum tengah hari.", "en": "Wake at 02:30, jeep to Penanjakan, then the sand sea and crater. Breakfast, then back to Malang before noon."}}]$j$::jsonb,$j$[{"id": "Penginapan 1 malam", "en": "1 night guesthouse"}, {"id": "Jeep 4x4 bersama pengemudi lokal", "en": "4x4 jeep with a local driver"}, {"id": "Tiket masuk TNBTS", "en": "TNBTS entrance ticket"}, {"id": "Sarapan dan makan malam", "en": "Breakfast and dinner"}, {"id": "Transportasi Malang pulang-pergi", "en": "Malang round-trip transport"}]$j$::jsonb,$j$[{"id": "Sewa jaket atau kuda ke kawah", "en": "Jacket hire or horse ride to the crater"}, {"id": "Makan siang", "en": "Lunch"}, {"id": "Pengeluaran pribadi dan oleh-oleh", "en": "Personal expenses and souvenirs"}]$j$::jsonb,'published',20) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,kind=excluded.kind,destination_id=excluded.destination_id,duration_days=excluded.duration_days,price_from=excluded.price_from,price_note=excluded.price_note,highlights=excluded.highlights,itinerary=excluded.itinerary,included=excluded.included,excluded=excluded.excluded,status='published',sort=excluded.sort;
insert into public.packages(slug,title,summary,kind,destination_id,duration_days,price_from,price_note,highlights,itinerary,included,excluded,status,sort) values ('family-trip-bali',$j${"id": "Paket Keluarga Bali 4 Hari", "en": "Bali Family Package, 4 Days"}$j$::jsonb,$j${"id": "Ritme santai untuk keluarga dengan anak: rute pendek, sopir ramah, dan banyak waktu istirahat di antara tempat wisata.", "en": "A relaxed pace for families with kids: short routes, a friendly driver and plenty of rest between sights."}$j$::jsonb,'family',(select id from public.destinations where slug='bali'),4,3200000,$j${"id": "Harga per keluarga (hingga 5 orang), mobil dan sopir. Contoh harga.", "en": "Price per family (up to 5 people), car and driver. Sample price."}$j$::jsonb,$j$[{"id": "Sawah berundak Tegallalang dan ayunan untuk anak", "en": "Tegallalang rice terraces with swings for the kids"}, {"id": "Pantai Nusa Dua yang ombaknya tenang", "en": "Calm-water beaches at Nusa Dua"}, {"id": "Pura Uluwatu saat senja", "en": "Uluwatu Temple at dusk"}]$j$::jsonb,$j$[{"title": {"id": "Ubud dan sekitarnya", "en": "Ubud and around"}, "text": {"id": "Jemput bandara, makan siang, lalu Tegallalang dan Monkey Forest. Check-in hotel di Ubud.", "en": "Airport pickup, lunch, then Tegallalang and the Monkey Forest. Hotel check-in in Ubud."}}, {"title": {"id": "Bali tengah", "en": "Central Bali"}, "text": {"id": "Kintamani, kopi luwak tasting, lalu Tirta Empul. Pulang awal supaya anak sempat istirahat.", "en": "Kintamani, coffee tasting, then Tirta Empul. Back early so the kids can rest."}}, {"title": {"id": "Pantai dan Uluwatu", "en": "Beaches and Uluwatu"}, "text": {"id": "Pagi di Nusa Dua atau Melasti, siang bebas, sore ke Uluwatu untuk sunset dan pertunjukan kecak.", "en": "Morning at Nusa Dua or Melasti, free afternoon, then Uluwatu for sunset and the kecak dance."}}, {"title": {"id": "Belanja dan pulang", "en": "Shopping and departure"}, "text": {"id": "Sukawati atau Krishna untuk oleh-oleh, lalu antar ke bandara sesuai jadwal penerbangan.", "en": "Sukawati or Krishna for souvenirs, then airport transfer to match your flight."}}]$j$::jsonb,$j$[{"id": "Mobil dan sopir 4 hari", "en": "Car and driver for 4 days"}, {"id": "BBM, parkir, dan tol", "en": "Fuel, parking and tolls"}, {"id": "Kursi bayi atas permintaan", "en": "Child seat on request"}, {"id": "Air mineral dan tisu basah", "en": "Water and wet wipes"}]$j$::jsonb,$j$[{"id": "Hotel dan makan", "en": "Hotel and meals"}, {"id": "Tiket masuk wisata", "en": "Attraction tickets"}, {"id": "Tiket pesawat/kereta ke kota keberangkatan", "en": "Flights or train tickets to the departure city"}]$j$::jsonb,'published',30) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,kind=excluded.kind,destination_id=excluded.destination_id,duration_days=excluded.duration_days,price_from=excluded.price_from,price_note=excluded.price_note,highlights=excluded.highlights,itinerary=excluded.itinerary,included=excluded.included,excluded=excluded.excluded,status='published',sort=excluded.sort;
insert into public.packages(slug,title,summary,kind,destination_id,duration_days,price_from,price_note,highlights,itinerary,included,excluded,status,sort) values ('open-trip-lombok-gili',$j${"id": "Open Trip Lombok dan Gili Trawangan 3 Hari 2 Malam", "en": "Lombok and Gili Trawangan Open Trip, 3 Days 2 Nights"}$j$::jsonb,$j${"id": "Pantai selatan Lombok, desa Sasak, dan snorkeling bersama penyu di Gili Trawangan dalam satu perjalanan ringkas.", "en": "Lombok south coast, Sasak village and snorkelling with turtles at Gili Trawangan in one compact trip."}$j$::jsonb,'open',(select id from public.destinations where slug='lombok'),3,1450000,$j${"id": "Per orang, berbagi kamar (twin sharing), minimal 6 peserta. Contoh harga.", "en": "Per person, twin sharing, minimum 6 participants. Sample price."}$j$::jsonb,$j$[{"id": "Pantai Tanjung Aan dan Bukit Merese", "en": "Tanjung Aan beach and Merese Hill"}, {"id": "Snorkeling penyu di tiga titik Gili", "en": "Turtle snorkelling at three Gili spots"}, {"id": "Cidomo keliling Gili Trawangan", "en": "A cidomo ride around Gili Trawangan"}]$j$::jsonb,$j$[{"title": {"id": "Bandara ke Kuta Mandalika", "en": "Airport to Kuta Mandalika"}, "text": {"id": "Jemput bandara Lombok, Desa Sade, lalu Tanjung Aan dan Bukit Merese saat senja.", "en": "Lombok airport pickup, Sade village, then Tanjung Aan and Merese Hill at sunset."}}, {"title": {"id": "Menyeberang ke Gili", "en": "Crossing to the Gilis"}, "text": {"id": "Perjalanan ke Bangsal, speedboat ke Gili Trawangan. Snorkeling tiga titik, makan siang, dan sore bebas.", "en": "Drive to Bangsal, speedboat to Gili Trawangan. Three snorkelling spots, lunch and a free afternoon."}}, {"title": {"id": "Pagi di Gili, pulang", "en": "Morning on the Gili, departure"}, "text": {"id": "Sunrise di dermaga, sarapan, lalu kembali ke daratan dan antar ke bandara.", "en": "Sunrise on the pier, breakfast, then back to the mainland and the airport transfer."}}]$j$::jsonb,$j$[{"id": "Hotel 2 malam (twin sharing)", "en": "2 nights hotel (twin sharing)"}, {"id": "Speedboat pulang-pergi ke Gili", "en": "Return speedboat to the Gili"}, {"id": "Peralatan snorkeling dan pemandu", "en": "Snorkel gear and guide"}, {"id": "Transport Lombok", "en": "Lombok transport"}, {"id": "Sarapan 2x, makan siang 2x", "en": "2 breakfasts, 2 lunches"}]$j$::jsonb,$j$[{"id": "Tiket pesawat/kereta ke kota keberangkatan", "en": "Flights or train tickets to the departure city"}, {"id": "Makan malam", "en": "Dinner"}, {"id": "Tiket masuk lokasi tertentu", "en": "Selected entrance fees"}]$j$::jsonb,'published',40) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,kind=excluded.kind,destination_id=excluded.destination_id,duration_days=excluded.duration_days,price_from=excluded.price_from,price_note=excluded.price_note,highlights=excluded.highlights,itinerary=excluded.itinerary,included=excluded.included,excluded=excluded.excluded,status='published',sort=excluded.sort;
insert into public.packages(slug,title,summary,kind,destination_id,duration_days,price_from,price_note,highlights,itinerary,included,excluded,status,sort) values ('open-trip-karimunjawa',$j${"id": "Open Trip Karimunjawa 3 Hari 2 Malam", "en": "Karimunjawa Open Trip, 3 Days 2 Nights"}$j$::jsonb,$j${"id": "Island hopping di perairan jernih Karimunjawa: snorkeling, hiu karang, dan senja di Pulau Menjangan.", "en": "Island hopping across the clear waters of Karimunjawa: snorkelling, reef sharks and sunsets at Menjangan."}$j$::jsonb,'open',(select id from public.destinations where slug='karimunjawa'),3,1350000,$j${"id": "Per orang, berbagi kamar homestay, minimal 8 peserta, belum termasuk tiket kapal ke pulau. Contoh harga.", "en": "Per person, shared homestay room, minimum 8 participants, ferry to the island not included. Sample price."}$j$::jsonb,$j$[{"id": "Snorkeling di Pulau Cemara Kecil dan Tanjung Gelam", "en": "Snorkelling at Cemara Kecil and Tanjung Gelam"}, {"id": "Melihat hiu karang di penangkaran Menjangan Besar", "en": "Meet reef sharks at the Menjangan Besar enclosure"}, {"id": "Sunset di dermaga Alun-alun", "en": "Sunset at the Alun-alun pier"}]$j$::jsonb,$j$[{"title": {"id": "Jepara ke Karimunjawa", "en": "Jepara to Karimunjawa"}, "text": {"id": "Berkumpul di pelabuhan Jepara, kapal cepat atau KMP ke pulau. Check-in homestay, sore menikmati senja.", "en": "Meet at Jepara port, fast boat or ferry to the island. Homestay check-in, sunset in the evening."}}, {"title": {"id": "Island hopping", "en": "Island hopping"}, "text": {"id": "Kapal sewa membawa kita ke empat titik snorkeling, makan siang di pulau, dan malam barbeque ikan.", "en": "A chartered boat takes us to four snorkelling spots, lunch on an island and a fish barbecue in the evening."}}, {"title": {"id": "Pagi santai dan pulang", "en": "Slow morning and return"}, "text": {"id": "Sunrise di dermaga, sarapan, lalu kapal kembali ke Jepara pada siang hari.", "en": "Pier sunrise, breakfast, then the boat back to Jepara at midday."}}]$j$::jsonb,$j$[{"id": "Homestay 2 malam", "en": "2 nights homestay"}, {"id": "Kapal island hopping dan alat snorkeling", "en": "Island-hopping boat and snorkel gear"}, {"id": "Pemandu lokal", "en": "Local guide"}, {"id": "Makan 5x dan BBQ ikan", "en": "5 meals and a fish barbecue"}]$j$::jsonb,$j$[{"id": "Tiket kapal Jepara-Karimunjawa pulang-pergi", "en": "Jepara-Karimunjawa return ferry"}, {"id": "Dokumentasi bawah air", "en": "Underwater photos"}, {"id": "Pengeluaran pribadi dan oleh-oleh", "en": "Personal expenses and souvenirs"}]$j$::jsonb,'published',50) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,kind=excluded.kind,destination_id=excluded.destination_id,duration_days=excluded.duration_days,price_from=excluded.price_from,price_note=excluded.price_note,highlights=excluded.highlights,itinerary=excluded.itinerary,included=excluded.included,excluded=excluded.excluded,status='published',sort=excluded.sort;
insert into public.packages(slug,title,summary,kind,destination_id,duration_days,price_from,price_note,highlights,itinerary,included,excluded,status,sort) values ('open-trip-raja-ampat',$j${"id": "Raja Ampat Homestay Trip 5 Hari 4 Malam", "en": "Raja Ampat Homestay Trip, 5 Days 4 Nights"}$j$::jsonb,$j${"id": "Piaynemo, Arborek, dan Pianemo dari homestay Waisai dengan kapal pribadi. Cocok untuk penyelam dan pencinta alam.", "en": "Piaynemo, Arborek and Pianemo from a Waisai homestay by private boat. Ideal for divers and nature lovers."}$j$::jsonb,'open',(select id from public.destinations where slug='raja-ampat'),5,8900000,$j${"id": "Per orang, minimal 4 peserta, belum termasuk tiket pesawat ke Sorong. Contoh harga.", "en": "Per person, minimum 4 participants, flights to Sorong not included. Sample price."}$j$::jsonb,$j$[{"id": "Panorama Piaynemo dari titik pandang karst", "en": "The Piaynemo karst viewpoint"}, {"id": "Snorkeling bersama pari manta di Manta Sandy", "en": "Snorkelling with manta rays at Manta Sandy"}, {"id": "Desa Arborek dan penyelaman tepat di dermaga", "en": "Arborek village with diving right off the jetty"}]$j$::jsonb,$j$[{"title": {"id": "Sorong ke Waisai", "en": "Sorong to Waisai"}, "text": {"id": "Jemput bandara Sorong, ferry ke Waisai, check-in homestay dan makan malam ikan bakar.", "en": "Sorong airport pickup, ferry to Waisai, homestay check-in and a grilled fish dinner."}}, {"title": {"id": "Piaynemo dan Telaga Bintang", "en": "Piaynemo and Star Lagoon"}, "text": {"id": "Kapal pribadi ke Piaynemo, trekking ringan ke titik pandang, lalu snorkeling di Telaga Bintang.", "en": "A private boat to Piaynemo, an easy hike to the viewpoint, then snorkelling in Star Lagoon."}}, {"title": {"id": "Arborek dan Manta Sandy", "en": "Arborek and Manta Sandy"}, "text": {"id": "Kunjungi desa Arborek, snorkeling di dermaga, siang ke Manta Sandy bila musim pari manta.", "en": "Visit Arborek village, snorkel off the pier and, in manta season, go to Manta Sandy."}}, {"title": {"id": "Pianemo dan Wayag opsional", "en": "Pianemo and optional Wayag"}, "text": {"id": "Trip ke Pianemo, atau Wayag dengan biaya tambahan dan izin khusus.", "en": "A trip to Pianemo, or Wayag at extra cost with a special permit."}}, {"title": {"id": "Kembali ke Sorong", "en": "Back to Sorong"}, "text": {"id": "Ferry pagi ke Sorong dan antar ke bandara.", "en": "Morning ferry to Sorong and an airport transfer."}}]$j$::jsonb,$j$[{"id": "Homestay 4 malam", "en": "4 nights homestay"}, {"id": "Kapal pribadi selama trip", "en": "Private boat for the whole trip"}, {"id": "Tiket masuk kawasan konservasi (PIN)", "en": "Marine park entry tag (PIN)"}, {"id": "Makan 3x sehari", "en": "Three meals a day"}, {"id": "Transfer bandara-pelabuhan", "en": "Airport and port transfers"}]$j$::jsonb,$j$[{"id": "Tiket pesawat ke Sorong", "en": "Flights to Sorong"}, {"id": "Penyelaman dan sewa alat selam", "en": "Diving and gear rental"}, {"id": "Biaya Wayag (opsional)", "en": "Wayag fee (optional)"}]$j$::jsonb,'published',60) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,kind=excluded.kind,destination_id=excluded.destination_id,duration_days=excluded.duration_days,price_from=excluded.price_from,price_note=excluded.price_note,highlights=excluded.highlights,itinerary=excluded.itinerary,included=excluded.included,excluded=excluded.excluded,status='published',sort=excluded.sort;
