insert into public.articles(slug,title,excerpt,body,category,tags,status,published_at) values ('kapan-waktu-terbaik-ke-raja-ampat',$j${"id": "Kapan Waktu Terbaik ke Raja Ampat?", "en": "When Is the Best Time to Visit Raja Ampat?"}$j$::jsonb,$j${"id": "Musim kering, arus laut, dan jadwal pari manta menentukan kapan perjalananmu terasa paling nyaman.", "en": "Dry season, sea currents and the manta calendar decide when your trip feels best."}$j$::jsonb,$j${"id": "## Singkatnya: Oktober sampai April\n\nUntuk sebagian besar wisatawan, **Oktober hingga April** adalah waktu paling nyaman. Laut cenderung tenang, jarak pandang bawah air bagus, dan kapal kecil lebih aman menyeberang antar pulau.\n\n## Bulan yang perlu diperhatikan\n\n- **Oktober-November**: laut teduh, harga belum puncak.\n- **Desember-Januari**: ramai liburan, pesan homestay jauh hari.\n- **Mei-September**: angin tenggara membuat ombak lebih tinggi di beberapa jalur, tapi pari manta di Manta Sandy lebih sering terlihat.\n\n## Yang sering terlupa\n\nTiket pesawat ke Sorong dan kuota homestay sering habis lebih cepat daripada yang dikira. **Kami sarankan memesan 2 sampai 3 bulan sebelumnya**, terutama untuk keberangkatan akhir tahun.\n\nIngin kami susunkan jadwalnya? Lihat [paket Raja Ampat](/packages/?slug=open-trip-raja-ampat) atau [hubungi admin](/contact/).", "en": "## In short: October to April\n\nFor most travellers, **October to April** is the most comfortable window. The sea is calm, underwater visibility is good and small boats cross between islands more safely.\n\n## Months to watch\n\n- **October-November**: calm seas, prices not yet at peak.\n- **December-January**: busy holidays, book homestays early.\n- **May-September**: southeast winds make some routes choppier, but manta rays at Manta Sandy are seen more often.\n\n## What people forget\n\nFlights to Sorong and homestay places sell out faster than expected. **We recommend booking 2 to 3 months ahead**, especially for year-end departures.\n\nWant us to plan it? See the [Raja Ampat trip](/packages/?slug=open-trip-raja-ampat) or [contact our admin](/contact/)."}$j$::jsonb,'Panduan',$j$["raja-ampat", "panduan"]$j$::jsonb,'published','2026-10-05T03:00:00+00:00') on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,body=excluded.body,category=excluded.category,tags=excluded.tags,status='published',published_at=excluded.published_at;
insert into public.articles(slug,title,excerpt,body,category,tags,status,published_at) values ('itinerary-karimunjawa-3-hari-2-malam',$j${"id": "Itinerary Karimunjawa 3 Hari 2 Malam yang Realistis", "en": "A Realistic 3-Day Karimunjawa Itinerary"}$j$::jsonb,$j${"id": "Jadwal yang tidak memaksa: kapan berangkat, apa yang dibawa, dan titik snorkeling yang layak.", "en": "A schedule that does not rush: when to leave, what to pack and which snorkelling spots are worth it."}$j$::jsonb,$j${"id": "## Hari 1: tiba dan santai\n\nKapal cepat dari Jepara membutuhkan sekitar **2 jam**. Setelah check-in homestay, jangan memaksa jadwal padat. Senja di dermaga Alun-alun sudah cukup.\n\n## Hari 2: island hopping\n\nBerangkat pagi saat air paling tenang. Titik yang biasa kami pilih:\n\n- Tanjung Gelam: pasir putih dan air dangkal.\n- Pulau Cemara Kecil: cocok untuk pemula.\n- Menjangan Besar: hiu karang di penangkaran.\n\n## Hari 3: pulang tanpa tergesa\n\nKapal kembali siang hari, jadi pagi masih cukup untuk sarapan dan sunrise.\n\n## Yang perlu dibawa\n\n- Tabir surya ramah karang\n- Baju ganti kering dalam kantong kedap air\n- Obat anti mabuk laut\n\nLihat [paket Karimunjawa](/packages/?slug=open-trip-karimunjawa) kami untuk harga dan fasilitas.", "en": "## Day 1: arrive and relax\n\nThe fast boat from Jepara takes about **2 hours**. After homestay check-in, do not force a packed schedule. Sunset at the Alun-alun pier is enough.\n\n## Day 2: island hopping\n\nLeave early when the water is calmest. Spots we usually choose:\n\n- Tanjung Gelam: white sand and shallow water.\n- Cemara Kecil: great for beginners.\n- Menjangan Besar: reef sharks in the enclosure.\n\n## Day 3: leave unhurried\n\nThe boat returns around midday, so mornings still fit breakfast and sunrise.\n\n## What to pack\n\n- Reef-safe sunscreen\n- Dry clothes in a waterproof bag\n- Seasickness tablets\n\nSee our [Karimunjawa trip](/packages/?slug=open-trip-karimunjawa) for price and inclusions."}$j$::jsonb,'Itinerary',$j$["karimunjawa", "itinerary"]$j$::jsonb,'published','2026-10-12T03:00:00+00:00') on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,body=excluded.body,category=excluded.category,tags=excluded.tags,status='published',published_at=excluded.published_at;
insert into public.articles(slug,title,excerpt,body,category,tags,status,published_at) values ('7-hal-sebelum-sewa-mobil-dengan-sopir',$j${"id": "7 Hal yang Perlu Dicek Sebelum Sewa Mobil dengan Sopir", "en": "7 Things to Check Before Renting a Car with a Driver"}$j$::jsonb,$j${"id": "Dari jam layanan sampai BBM dan tol: daftar singkat agar tidak ada biaya yang mengejutkan.", "en": "From service hours to fuel and tolls: a short checklist so no cost surprises you."}$j$::jsonb,$j${"id": "Sewa mobil dengan sopir terlihat sederhana, tapi detail kecil sering memengaruhi biaya akhir. Cek ini dulu:\n\n## 1. Jam layanan\nBiasanya 12 jam per hari. Tanyakan biaya per jam tambahan.\n\n## 2. BBM, tol, parkir\nApakah sudah termasuk atau ditagihkan terpisah?\n\n## 3. Makan dan penginapan sopir\nUntuk perjalanan menginap, ini perlu dibicarakan sejak awal.\n\n## 4. Kapasitas bagasi\nJumlah kursi tidak sama dengan jumlah koper. Sebutkan jumlah koper saat memesan.\n\n## 5. Kondisi dan tahun kendaraan\nMinta foto kendaraan sebenarnya.\n\n## 6. Kebijakan pembatalan\nKapan uang muka bisa kembali?\n\n## 7. Kontak darurat\nPastikan ada nomor admin yang aktif selama perjalanan.\n\n**Di GoNEST**, semua poin ini kami tuliskan di penawaran. Cek [armada kami](/vehicles/) atau [tanya admin](/contact/).", "en": "Renting a car with a driver looks simple, but small details change the final cost. Check these first:\n\n## 1. Service hours\nUsually 12 hours a day. Ask the hourly overtime rate.\n\n## 2. Fuel, tolls, parking\nIncluded, or billed separately?\n\n## 3. Driver meals and lodging\nFor overnight trips, settle this early.\n\n## 4. Luggage capacity\nSeats are not suitcases. Tell us how many bags when booking.\n\n## 5. Vehicle condition and year\nAsk for photos of the actual vehicle.\n\n## 6. Cancellation policy\nWhen can a deposit be refunded?\n\n## 7. Emergency contact\nMake sure an admin number is active during the trip.\n\n**At GoNEST**, we write all of this into the quote. See our [fleet](/vehicles/) or [ask our admin](/contact/)."}$j$::jsonb,'Tips',$j$["sewa-mobil", "tips"]$j$::jsonb,'published','2026-10-20T03:00:00+00:00') on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,body=excluded.body,category=excluded.category,tags=excluded.tags,status='published',published_at=excluded.published_at;
insert into public.articles(slug,title,excerpt,body,category,tags,status,published_at) values ('yogyakarta-3-hari-tanpa-terburu-buru',$j${"id": "Yogyakarta 3 Hari: Rute yang Tidak Membuat Capek", "en": "Yogyakarta in 3 Days: A Route That Will Not Wear You Out"}$j$::jsonb,$j${"id": "Borobudur di pagi hari, kota tua saat panas, Prambanan di senja. Urutan yang kami pakai bersama tamu.", "en": "Borobudur in the morning, the old city in the heat, Prambanan at dusk. The order we use with guests."}$j$::jsonb,$j${"id": "Kesalahan umum di Yogyakarta adalah memasukkan terlalu banyak tempat dalam satu hari. Urutan ini lebih nyaman:\n\n## Hari 1: kota tua\nKeraton dan Taman Sari di pagi hari saat udara masih sejuk, lalu makan siang gudeg dan istirahat. Malioboro cocok untuk sore.\n\n## Hari 2: Borobudur dan Merapi\nBerangkat pukul 04.00 agar sampai sebelum fajar. Setelah itu, **tidur siang** di hotel sebelum lanjut ke Kaliurang.\n\n## Hari 3: Prambanan\nPrambanan dan Ratu Boko paling indah saat senja. Sisakan waktu untuk oleh-oleh.\n\n## Tips kecil\n\n- Bawa topi dan sepatu nyaman.\n- Beli tiket candi lewat jalur resmi.\n- Hindari akhir pekan panjang bila bisa.\n\nKami menyusun versi pribadinya di [Private Trip Yogyakarta](/packages/?slug=private-trip-yogyakarta).", "en": "A common mistake in Yogyakarta is packing too many places into one day. This order is more comfortable:\n\n## Day 1: the old city\nThe Kraton and Taman Sari in the cool of the morning, then a gudeg lunch and a rest. Malioboro suits the afternoon.\n\n## Day 2: Borobudur and Merapi\nLeave at 04:00 to arrive before dawn. Afterwards, **take a nap** at the hotel before Kaliurang.\n\n## Day 3: Prambanan\nPrambanan and Ratu Boko are best at dusk. Leave time for souvenirs.\n\n## Small tips\n\n- Bring a hat and comfortable shoes.\n- Buy temple tickets through official channels.\n- Avoid long weekends if you can.\n\nWe build a private version in [Private Trip Yogyakarta](/packages/?slug=private-trip-yogyakarta)."}$j$::jsonb,'Itinerary',$j$["yogyakarta", "itinerary"]$j$::jsonb,'published','2026-11-02T03:00:00+00:00') on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,body=excluded.body,category=excluded.category,tags=excluded.tags,status='published',published_at=excluded.published_at;
insert into public.articles(slug,title,excerpt,body,category,tags,status,published_at) values ('lombok-atau-bali-pilih-yang-mana',$j${"id": "Lombok atau Bali? Cara Memilih Sesuai Gaya Liburanmu", "en": "Lombok or Bali? How to Choose for Your Holiday Style"}$j$::jsonb,$j${"id": "Keduanya indah, tapi ritmenya berbeda. Ini perbandingan jujur untuk membantumu memutuskan.", "en": "Both are beautiful, but the rhythm differs. An honest comparison to help you decide."}$j$::jsonb,$j${"id": "Pertanyaan ini paling sering kami terima. Jawabannya tergantung apa yang kamu cari.\n\n## Pilih Bali jika\n\n- Ingin banyak pilihan kuliner, kafe, dan hiburan.\n- Bepergian dengan keluarga yang butuh fasilitas lengkap.\n- Waktu terbatas dan ingin jarak antar tempat dekat.\n\n## Pilih Lombok jika\n\n- Mencari pantai yang lebih sepi.\n- Ingin snorkeling di Gili dengan suasana santai.\n- Suka alam, desa tradisional, atau pendakian Rinjani.\n\n## Anggaran\n\nBali umumnya menawarkan rentang harga lebih luas. Lombok sering lebih hemat untuk akomodasi dan makan, tetapi jarak antar objek lebih jauh sehingga transport perlu direncanakan.\n\nBingung? **Ceritakan rencanamu** lewat [halaman kontak](/contact/) dan kami bantu sarankan. Atau lihat [Paket Bali](/packages/?slug=family-trip-bali) dan [Trip Lombok](/packages/?slug=open-trip-lombok-gili).", "en": "This is the question we get most. The answer depends on what you are looking for.\n\n## Choose Bali if\n\n- You want lots of food, cafes and entertainment.\n- You travel with family that needs full facilities.\n- Your time is limited and you want short distances.\n\n## Choose Lombok if\n\n- You want quieter beaches.\n- You want relaxed snorkelling in the Gilis.\n- You like nature, traditional villages or climbing Rinjani.\n\n## Budget\n\nBali generally offers a wider price range. Lombok is often cheaper for lodging and food, but distances are longer so transport needs planning.\n\nUnsure? **Tell us your plan** on the [contact page](/contact/) and we will suggest. Or see the [Bali package](/packages/?slug=family-trip-bali) and the [Lombok trip](/packages/?slug=open-trip-lombok-gili)."}$j$::jsonb,'Panduan',$j$["lombok", "bali", "panduan"]$j$::jsonb,'published','2026-11-10T03:00:00+00:00') on conflict (slug) do update set title=excluded.title,excerpt=excluded.excerpt,body=excluded.body,category=excluded.category,tags=excluded.tags,status='published',published_at=excluded.published_at;
insert into public.promos(code,title,description,terms,type,value,ends_at,show_popup,active) select 'GONEST10',$j${"id": "Diskon 10% untuk Trip Pertamamu", "en": "10% Off Your First Trip"}$j$::jsonb,$j${"id": "Berlaku untuk pemesanan pertama paket trip apa pun. Sebutkan kode ini saat menghubungi admin.", "en": "Valid for your first booking of any trip package. Mention this code when you contact our admin."}$j$::jsonb,$j${"id": "Satu kali pakai per pelanggan. Tidak dapat digabung dengan promo lain. Tidak berlaku pada periode libur nasional.", "en": "One use per customer. Cannot be combined with other promos. Not valid during national holidays."}$j$::jsonb,'percent',10,'2027-03-31T16:59:59+00:00',true,true where not exists (select 1 from public.promos where upper(code)='GONEST10');
